    local alpha = "+ZYXWVUTSRQPONMLKJIHGFEDCBAzyxwvutsrqponmlkjihgfedcba9876543210/"
    for i = 1, #alpha do
        if alpha:sub(i, i) == c then return i - 1 end
    end
    return 0
end

